74	// mega_decoder_real_adamw_tc — the WIRED TC launcher. Boundary mirrors the scalar
75	// mega_decoder_real_adamw (dispatch.cpp extern-decls it with the same mirror
76	// types) EXCEPT it takes NO workspace pointer: the TC workspace is a different
77	// size from the scalar nCTA*total partials, so this TU allocates+owns it. `loss_out`
78	// still points into the caller's state[3*total] slot (dispatch reads it back).
79	//
80	// OPTID-GENERIC (owner baseline directive — all 33 cells on L3-TC): the fwd+bwd+
81	// grad-reduction is OPTIMIZER-INDEPENDENT (the same validated wgmma decoder kernel);
82	// ONLY the per-element optimizer TAIL (apply_optimizer<Opt>) differs, and that tail
83	// is the 14/0-apply-parity math already in opt_components.cuh. So this launcher
84	// takes `opt_id` (the OptId int) and dispatches to the matching kernel instantiation
85	// over the SAME state buffer. The state layout is [m | v | extra] (3*total) + loss:
86	//   * lion              uses m only (v/extra unread; bound harmlessly)
87	//   * adamw             uses m, v
88	//   * grokfast/grokadamw use m, v, ema  (ema == the `extra` slice, state + 2*total)
89	//   * neuralgrok        uses m, v, AND a psi-net weight pack the cell supplies in the
90	//                       `extra` slice (kPsiPackFloats floats); st.psi_W1/b1/W2 bind
91	//                       to those offsets, exactly as opt_components.cuh documents.
92	// The STAGED optimizers (prodigy/muon/SG11/SG15) and the model-coupled (looksam) and
93	// SG2 are NOT routed here — they need precompute stages / a 2nd backward / a sharpness
94	// ABI field that this single-launch path does not carry; dispatch.cpp gates them out
95	// (and wiring_check fails them loud with the cited reason). NeuralGrok is wired but
96	// its host-trained amplifier is a separate concern (the race fn gates it).
97	//
98	// ncta_cap: forwarded to the TC launcher (0 = one CTA/SM = full saturation, the
99	// shipped config). The race always passes 0.
100	cudaError_t mega_decoder_real_adamw_tc(
101	        PersistentContext ctx, float* params,
102	        const int* tokens, const int* targets, int B,
103	        float* state, float* grad, float* /*workspace_unused*/, float* loss_out,
104	        const int* sizes, const int* offsets,
105	        float lr, int step, const FusedScalars& scalars, cudaStream_t stream,
106	        int ncta_cap, int opt_id) {
107	    (void)sizes; (void)offsets;  // TC kernel reads kDecSizes/kDecOffsets directly.
108	
109	    const int64_t total = kDecTotalElems;
110	    const int T = B * dec::kSeq;
111	
112	    int dev = 0;
113	    cudaError_t err = cudaGetDevice(&dev);
114	    if (err != cudaSuccess) return err;
115	    int n_sms = 1;
116	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
117	    if (err != cudaSuccess) return err;
118	    int nCTA = n_sms;
119	    if (ncta_cap > 0 && ncta_cap < nCTA) nCTA = ncta_cap;
120	
121	    const int64_t need = dec_tc_workspace_floats(T, B, nCTA);
122	    DecTcLauncherScratch& sc = dec_tc_launcher_scratch(dev, need);
123	
124	    // Re-point the ctx counters at THIS TU's cached counters (dispatch.cpp built
125	    // ctx pointing at its scalar DecoderScratch counters; the TC launcher zeroes
126	    // them per-launch, but they must be the ones this scratch owns so the grid
127	    // barrier is consistent with the workspace).
128	    ctx.g_next_task   = sc.g_next;
129	    ctx.g_arrived     = sc.g_arrived;
130	    ctx.g_generation  = sc.g_generation;
131	    ctx.n_tasks       = kDecNumTensors;  // parameter tensors for reduce+opt phases
132	
133	    // Bind the optimizer state slices. [m | v | extra] over the SAME state buffer;
134	    // each tail reads only its own buffers (opt_components.cuh guarantees unused
135	    // pointers are never dereferenced). ema/psi-net live in the `extra` slice.
136	    float* const m_slice     = state;
137	    float* const v_slice     = state + total;
138	    float* const extra_slice = state + 2 * total;
139	    FusedOptState st;
140	    st.exp_avg    = m_slice;
141	    st.exp_avg_sq = v_slice;
142	    st.ema        = extra_slice;          // grokfast/grokadamw slow-grad EMA
143	    // NeuralGrok psi-net pack (kPsiPackFloats floats at the head of `extra`): the
144	    // cell places [psi_W1 | psi_b1 | psi_W2 | psi_b2] there; bind the device pointers
145	    // so the apply reads real weights (psi_b2 is read on-device from psi_W2[kPsiHidden]).
146	    st.psi_W1     = extra_slice + kPsiW1Off;
147	    st.psi_b1     = extra_slice + kPsiB1Off;
148	    st.psi_W2     = extra_slice + kPsiW2Off;
149	    apply_scalars(st, scalars);   // FULL scalar set (un-frozen bc1/bc2/...)
150	    st.lr = lr;
151	
152	    DecoderTokenCtx tok;
153	    tok.tokens    = tokens;
154	    tok.targets   = targets;
155	    tok.B         = B;
156	    tok.workspace = sc.workspace;
157	    tok.loss_out  = loss_out;
158	
159	    // Dispatch to the matching kernel instantiation. The fwd+bwd is identical across
160	    // these OptIds; the template differs ONLY in the P3 apply_optimizer<Opt> tail.
161	    // Unsupported opt_ids return cudaErrorInvalidValue → dispatch.cpp throws LOUD (no
162	    // silent scalar/adamw fallback — the no-suppression rule). The STAGED/model-coupled
163	    // optimizers are intentionally NOT cases here (they cannot run as a single launch).
164	    switch (static_cast<OptId>(opt_id)) {
165	        case OptId::AdamW:
166	            return launch_fused_decoder_megakernel_tc<OptId::AdamW>(
167	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
168	        case OptId::Lion:
169	            return launch_fused_decoder_megakernel_tc<OptId::Lion>(
170	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
171	        case OptId::Grokfast:
172	            return launch_fused_decoder_megakernel_tc<OptId::Grokfast>(
173	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
174	        case OptId::GrokAdamW:
175	            return launch_fused_decoder_megakernel_tc<OptId::GrokAdamW>(
176	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
177	        case OptId::NeuralGrok:
178	            return launch_fused_decoder_megakernel_tc<OptId::NeuralGrok>(
179	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
180	        default:
181	            return cudaErrorInvalidValue;  // STAGED/coupled opt not single-launch TC
182	    }
183	}
184	
185	}}}  // namespace sg::fused::sm90
