538	// Host helper: the EXACT CTA count launch_fused_mamba_megakernel_tc<Opt> will use
539	// (occ·n_sms with occupancy-fill, or the cap). The caller MUST size the workspace
540	// with this — the per-CTA scratch/partials are nCTA·slab, so sizing for n_sms while
541	// the launcher runs occ·n_sms would overflow. Returns 0 on a CUDA-attr failure (the
542	// caller should treat that as "fall back to a conservative larger size").
543	template <OptId Opt>
544	int mb_tc_launched_nctas(int dev, int ncta_cap) {
545	    int n_sms = 0;
546	    if (cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev) != cudaSuccess) return 0;
547	    int occ = 0;
548	    if (cudaOccupancyMaxActiveBlocksPerMultiprocessor(
549	            &occ, (const void*)&fused_mamba_megakernel_tc<Opt>, SG_MB_TC_MEGA_BLOCK, 0) != cudaSuccess)
550	        return 0;
551	    if (occ < 1) return 0;
552	    unsigned waves = (SG_MBTC_MIN_BLOCKS_PER_SM >= 2 && occ > 1) ? (unsigned)occ : 1u;
553	    unsigned launch_ctas = (unsigned)n_sms * waves;
554	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
555	    return (int)launch_ctas;
556	}
557	
558	template <OptId Opt>
559	cudaError_t launch_fused_mamba_megakernel_tc(
560	        PersistentContext ctx, float* params, MambaTokenCtx tok,
561	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
562	        int ncta_cap = 0) {
563	    int dev = 0;
564	    cudaError_t err = cudaGetDevice(&dev);
565	    if (err != cudaSuccess) return err;
566	    int n_sms = 0;
567	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
568	    if (err != cudaSuccess) return err;
569	
570	    int occ = 0;
571	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
572	        &occ, (const void*)&fused_mamba_megakernel_tc<Opt>, SG_MB_TC_MEGA_BLOCK,
573	        /*dynamicSMemBytes=*/0);
574	    if (err != cudaSuccess) return err;
575	    if (occ < 1) return cudaErrorLaunchOutOfResources;
576	
577	    // OCCUPANCY-FILL: at min-blocks≥2 the kernel is built ≤128 reg/thread so `occ`
578	    // CTAs co-reside per SM. Launch occ·n_sms CTAs (one full residency set) so the
579	    // co-resident CTAs hide each other's HBM latency across the scan/conv/LN phases
580	    // that run fully exposed at occ=1 — the persistent grid barrier rendezvous is
581	    // over the LAUNCHED count and occ·n_sms are guaranteed simultaneously resident,
582	    // so it stays hang-free. Determinism is per fixed launched nCTA (ascending-CTA
583	    // reduce). At min-blocks==1 (shipped default) occ==1 → identical to before.
584	    unsigned waves = (SG_MBTC_MIN_BLOCKS_PER_SM >= 2 && occ > 1) ? (unsigned)occ : 1u;
585	    unsigned launch_ctas = (unsigned)n_sms * waves;
586	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
587	    ctx.n_ctas = launch_ctas;
588	    // B%16: the dW K-loop contracts K=T=B·8 in 16-step atoms. It ALSO guarantees
589	    // FULL tiles (T%kTileM==0 for kTileM∈{64,128}), which the projection GEMMs
590	    // REQUIRE — they process a compile-time M-extent of kTileM rows (kAtomsM
591	    // atoms), NOT the runtime `nrows`; a partial final tile would feed garbage
592	    // pad rows to the wgmma while the scalar scan/conv loops process only nsamp.
593	    // (A future relaxation to B%2 would satisfy the K-atom reason but silently
594	    // break partial tiles — keep B%16.)
595	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
596	    // SPLIT-K dW (G>1) needs equal 16-aligned K-chunks: G must divide k_steps_total
597	    // = T/16 = B·kSeq/16 = B/2 (kSeq=8). With B%16==0, B/2%4==0, so G∈{1,2,4} are
598	    // always legal; a larger/odd G that doesn't divide B/2 would silently DROP the
599	    // remainder k-steps from every dW (a correctness bug) — REFUSE loudly instead.
600	    if (mbtc::kMbDwSplitK > 1 && (((int64_t)tok.B * mb::kSeq / wgs::kWgmmaAtomK) % mbtc::kMbDwSplitK) != 0)
601	        return cudaErrorInvalidValue;
602	
603	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
604	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
605	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
606	
607	    dim3 grid(launch_ctas), block(SG_MB_TC_MEGA_BLOCK);
608	    fused_mamba_megakernel_tc<Opt><<<grid, block, 0, stream>>>(
609	        ctx, params, tok, grad, lr, step, st);
610	    return cudaGetLastError();
611	}
