482	        const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
483	        const int64_t ecnt = base + (cta < rem ? 1 : 0);
484	        // Thread-local partial → block reduce (fixed tree) → thread0 writes the slot.
485	        float tsum = 0.0f;
486	        for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
487	            const float gv = grad[e0 + i];
488	            tsum += gv * gv;
489	        }
490	        // Block reduction via the smem the TC GEMM already owns (sm.red, fp32).
491	        float* red = sm.red;
492	        red[threadIdx.x] = tsum;
493	        __syncthreads();
494	        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
495	            if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
496	            __syncthreads();
497	        }
498	        if (threadIdx.x == 0) sq_part[cta] = red[0];
499	        bar.sync();   // B2.5a: all per-CTA sum-of-squares partials complete
500	        // CTA0 ascending-order reduce → total_norm → clip_coef (deterministic).
501	        if (cta == 0 && threadIdx.x == 0) {
502	            double ss = 0.0;
503	            for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
504	            const float total_norm = sqrtf((float)ss);
505	            float coef = 1.0f;
506	            if (st.grad_clip > 0.0f && total_norm > st.grad_clip)
