604	// saturation); a memory-constrained TEST passes a small cap so the per-CTA
605	// scratch fits (the scratch is nCTA×slab). Determinism is preserved per fixed
606	// nCTA (the dW/embedding owner maps are functions of nCTA).
607	template <OptId Opt>
608	cudaError_t launch_fused_decoder_megakernel_tc(
609	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
610	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
611	        int ncta_cap = 0) {
612	    int dev = 0;
613	    cudaError_t err = cudaGetDevice(&dev);
614	    if (err != cudaSuccess) return err;
615	    int n_sms = 0;
616	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
617	    if (err != cudaSuccess) return err;
618	
619	    // Hang-freedom: certify one block/SM occupancy with the ACTUAL dynamic smem
620	    // (0 here — DecTcSmem is static). If the static smem + 200-reg consumer
621	    // can't place one block/SM, REFUSE (the grid barrier would hang).
622	    int occ = 0;
